package com.fertiplus.order;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class OrderPersistenceService { private final OrderRepository orders; private final OutboxRepository outbox; private final ObjectMapper mapper; public OrderPersistenceService(OrderRepository orders,OutboxRepository outbox,ObjectMapper mapper){this.orders=orders;this.outbox=outbox;this.mapper=mapper;} @Transactional public OrderEntity persist(OrderController.CreateOrder req,String key,double total){OrderEntity order=new OrderEntity(req.customerId(),req.productId(),req.quantity(),total,"PENDING",key);orders.save(order);try{outbox.save(new OutboxEvent("orders.created",order.id,mapper.writeValueAsString(new OrderService.OrderCreated(order.id,order.customerId,order.productId,order.quantity,order.total))));}catch(JsonProcessingException e){throw new IllegalStateException("Could not serialize order event",e);}return order;} }
